const CLRS = ["#0090e0", "#e0b000", "#b82828"];
const NUM_RECTS = 24;
const NUM_LINES = 12;
const PTS = [29.5, 43];

function setup() {
  createCanvas(~~((windowHeight * 210) / 297), windowHeight);
	describe("recode Adam Fuhrer: colored lines forming 3d planes consisting of 12 lines");
	frameRate(5);
  noFill();

	blendMode(BLEND);
  background("#cbc8be");

	blendMode(MULTIPLY);
	drawPoints();
}

function drawPoints() {
  // points
  const numX = PTS[0] + 1;
  const numY = PTS[1] + 1;
  stroke("grey");
  strokeWeight(2);
  for (j = fract(numY); j < numY; j++) {
    for (i = fract(numX); i < numX; i++) {
      if (i === 0 || j === 0) continue;
      const x = map(i, 0, numX, 0, width);
      const y = map(j, 0, numY, 0, height);
      point(x, y);
    }
  }
}

function draw() {
	if (frameCount > NUM_RECTS + 0 * NUM_LINES) {
		// noLoop() removed for animation
		return;
	}

  // trapez
  const dst = Math.round(width / 10);
  const xStr1 = dst;
  const xEnd1 = width - xStr1;
  const xStr2 = dst * 2;
  const xEnd2 = width - xStr2;
  const yStr1 = dst * 2;
  const yEnd1 = height - yStr1;
  const yStr2 = dst * 3;
  const yEnd2 = height - yStr2;
  // for (let i = 0; i < NUM_RECTS; i++) {
		const i = ~~ (frameCount / 1); // NUM_LINES
    const x1 = map(i, 0, NUM_RECTS - 1, xStr1, xEnd1);
    const x2 = map(i, 0, NUM_RECTS - 1, xStr2, xEnd2);
    const y1 = map(i, 0, NUM_RECTS - 1, yStr1, yEnd1);
    const y2 = map(i, 0, NUM_RECTS - 1, yStr2, yEnd2);
    stroke(CLRS[i % CLRS.length]);
    for (let j = 0; j < NUM_LINES; j++) {
			// const j = ~~ (frameCount % NUM_LINES)
      const f = j / (NUM_LINES - 1);
      const xs = lerp(xStr1, xStr2, f);
      const xe = lerp(xEnd1, xEnd2, f);
      var y = lerp(y1, y2, f);
			const dy = 0; // (i !== 7) ? 0 : (height/2+(height/2-y)-y) ;
      dLine(xs, y, xe, y + dy);
    }
  // }
}

function dLine(x1, y1, x2, y2) {
  var dst = dist(x1, y1, x2, y2);
  // line(x1, y1, x2, y2);
  for (let i = 0; i <= dst; i++) {
    var f = i/dst;
    var x = lerp(x1, x2, f);
    var y = lerp(y1, y2, f);
    const t = abs(0.5-f) * 3 + 1.5; // 3--1.5--3
    strokeWeight(t);
    point(x, y);
  }
}
